    39→/**
    40→ */
    41→public class DruidDefaultSerializersModule extends SimpleModule
    42→{
    43→  public DruidDefaultSerializersModule()
    44→  {
    45→    super("Druid default serializers");
    46→
    47→    JodaStuff.register(this);
    48→
    49→    addDeserializer(
    50→        DateTimeZone.class,
    51→        new JsonDeserializer<DateTimeZone>()
    52→        {
    53→          @Override
    54→          public DateTimeZone deserialize(JsonParser jp, DeserializationContext ctxt)
    55→              throws IOException
    56→          {
    57→            String tzId = jp.getText();
    58→            return DateTimes.inferTzFromString(tzId);
    59→          }
    60→        }
    61→    );
    62→    addSerializer(
    63→        DateTimeZone.class,
    64→        new JsonSerializer<DateTimeZone>()
    65→        {
    66→          @Override
    67→          public void serialize(
    68→              DateTimeZone dateTimeZone,
    69→              JsonGenerator jsonGenerator,
    70→              SerializerProvider serializerProvider
    71→          ) throws IOException
    72→          {
    73→            jsonGenerator.writeString(dateTimeZone.getID());
    74→          }
    75→        }
    76→    );
    77→    addSerializer(
    78→        Sequence.class,
    79→        new JsonSerializer<Sequence>()
    80→        {
    81→          @Override
    82→          public void serialize(Sequence value, final JsonGenerator jgen, SerializerProvider provider)
    83→              throws IOException
    84→          {
    85→            jgen.writeStartArray();
    86→            value.accumulate(
    87→                null,
    88→                new Accumulator<Object, Object>()
    89→                {
    90→                  @Override
    91→                  public Object accumulate(Object o, Object o1)
    92→                  {
    93→                    try {
    94→                      jgen.writeObject(o1);
    95→                    }
    96→                    catch (IOException e) {
    97→                      throw new RuntimeException(e);
    98→                    }
    99→                    return null;
   100→                  }
   101→                }
   102→            );
   103→            jgen.writeEndArray();
   104→          }
   105→        }
   106→    );
   107→    addSerializer(
   108→        Yielder.class,
   109→        new JsonSerializer<Yielder>()
   110→        {
   111→          @Override
   112→          public void serialize(Yielder yielder, final JsonGenerator jgen, SerializerProvider provider)
   113→              throws IOException
   114→          {
   115→            try {
   116→              jgen.writeStartArray();
   117→              while (!yielder.isDone()) {
   118→                final Object o = yielder.get();
   119→                jgen.writeObject(o);
   120→                yielder = yielder.next(null);
   121→              }
   122→              jgen.writeEndArray();
   123→            }
   124→            finally {
   125→              yielder.close();
   126→            }
   127→          }
   128→        }
   129→    );
   130→    addSerializer(ByteOrder.class, ToStringSerializer.instance);
   131→    addDeserializer(
   132→        ByteOrder.class,
   133→        new JsonDeserializer<ByteOrder>()
   134→        {
   135→          @Override
   136→          public ByteOrder deserialize(JsonParser jp, DeserializationContext ctxt) throws IOException
   137→          {
   138→            if (ByteOrder.BIG_ENDIAN.toString().equals(jp.getText())) {
   139→              return ByteOrder.BIG_ENDIAN;
   140→            }
   141→            return ByteOrder.LITTLE_ENDIAN;
   142→          }
   143→        }
   144→    );
   145→  }
   146→}
