    32→public class JavaScriptParseSpec extends ParseSpec
    33→{
    34→  private final String function;
    35→  private final JavaScriptConfig config;
    36→
    37→  // This variable is lazily initialized to avoid unnecessary JavaScript compilation during JSON serde
    38→  private JavaScriptParser parser;
    39→
    40→  @JsonCreator
    41→  public JavaScriptParseSpec(
    42→      @JsonProperty("timestampSpec") TimestampSpec timestampSpec,
    43→      @JsonProperty("dimensionsSpec") DimensionsSpec dimensionsSpec,
    44→      @JsonProperty("function") String function,
    45→      @JacksonInject JavaScriptConfig config
    46→  )
    47→  {
    48→    super(timestampSpec, dimensionsSpec);
    49→
    50→    this.function = function;
    51→    this.config = config;
    52→  }
