    54→  @JsonProperty("function")
    55→  public String getFunction()
    56→  {
    57→    return function;
    58→  }
    59→
    60→  @Override
    61→  public Parser<String, Object> makeParser()
    62→  {
    63→    // JavaScript configuration should be checked when it's actually used because someone might still want Druid
    64→    // nodes to be able to deserialize JavaScript-based objects even though JavaScript is disabled.
    65→    Preconditions.checkState(config.isEnabled(), "JavaScript is disabled");
    66→    parser = parser == null ? new JavaScriptParser(function) : parser;
    67→    return parser;
    68→  }
    69→
    70→  @Override
    71→  public ParseSpec withTimestampSpec(TimestampSpec spec)
    72→  {
    73→    return new JavaScriptParseSpec(spec, getDimensionsSpec(), function, config);
    74→  }
    75→
    76→  @Override
    77→  public ParseSpec withDimensionsSpec(DimensionsSpec spec)
    78→  {
    79→    return new JavaScriptParseSpec(getTimestampSpec(), spec, function, config);
    80→  }
    81→
    82→}
